css:
@font-face {
  font-family: "THSarabun";
  src: url("/assets/erpnext_thailand/fonts/THSarabun.ttf");
}
@page { size: A4 portrait; margin: 0; }
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { margin: 0; padding: 0; }
body {
  font-family: "Sarabun", "TH Sarabun New", "Noto Sans Thai", "THSarabun", Arial, sans-serif;
  font-size: 9pt;
  color: #111;
}

.print-format { padding: 0 !important; margin: 0 !important; min-height: unset !important; max-width: unset !important; }
.print-format-preview { padding: 0 !important; }
.page {
  width: 210mm;
  height: 297mm;
  position: relative;
  overflow: hidden;
  page-break-after: always;
  background-size: 210mm 297mm;
  background-repeat: no-repeat;
  font-family: "THSarabun", "Sarabun", Arial, sans-serif;
  font-size: 12pt;
  color: #111;
}
.page:last-child { page-break-after: auto; }
.f { position: absolute; line-height: 1.08; white-space: normal; }

.field { position: absolute; line-height: 1.08; white-space: nowrap; }
.text-right { text-align: right; }
.amount { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.tr { text-align: right; }
.tc { text-align: center; }
.nowrap { white-space: nowrap; overflow: hidden; }
.small { font-size: 10.5pt; }
.items table { width: 100%; border-collapse: collapse; table-layout: fixed; }
.items td { padding: 0.8mm 1mm; vertical-align: top; line-height: 1.05; }

.page { background-image: url("/assets/connect_diagnostics_core/images/print_formats/ex_qt6904030_1.webp"); }

.party-name { top: 56.5mm; left: 19mm; width: 88mm; }
.party-address { top: 64mm; left: 18mm; width: 88mm; line-height: 1.12; }
.party-tax { top: 87mm; left: 23mm; width: 77mm; }
.doc-no { top: 44mm; left: 180mm; width: 20mm; text-align: center; }
.doc-date { top: 56.5mm; left: 145mm; width: 45mm; }
.due-date { top: 64mm; left: 145mm; width: 45mm; }
.reference { top: 94mm; left: 18mm; width: 80mm; }
.terms { top: 84.5mm; left: 145mm; width: 45mm; }
.items { top: 115mm; left: 14mm; width: 190mm; font-size: 10.8pt; }
.col-no { width: 12mm; text-align: center; }
.item-no-shift { display: inline-block; transform: translateX(-8mm); }
.col-desc { width: 86mm; }
.item-desc-shift { display: inline-block; transform: translate(0, -2mm); }
.col-qty { width: 30mm; text-align: center; }
.col-rate { width: 30mm; text-align: right; }
.col-amount { width: 32mm; text-align: right; }
.remarks { top: 225mm; left: 18mm; width: 82mm; }
.total { top: 191mm; left: 173mm; width: 30mm; }
.discount { display: none; }
.vat { top: 199.2mm; left: 173mm; width: 30mm; }
.grand { top: 207.5mm; left: 173mm; width: 30mm; font-weight: 700; }
